CREATE TABLE ai_provider(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,name VARCHAR(128) NOT NULL,provider_type VARCHAR(64) NOT NULL,version VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_ai_provider_tenant_name UNIQUE(tenant_id,name));
CREATE TABLE ai_prompt(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,key_name VARCHAR(128) NOT NULL,version INT NOT NULL,classification VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_ai_prompt_tenant_key_version UNIQUE(tenant_id,key_name,version));
CREATE TABLE ai_tool(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,name VARCHAR(128) NOT NULL,version VARCHAR(32) NOT NULL,enabled BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,CONSTRAINT uq_ai_tool_tenant_name UNIQUE(tenant_id,name));
CREATE TABLE ai_session(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,correlation_id UUID NOT NULL,user_id UUID,created_at TIMESTAMPTZ NOT NULL,expires_at TIMESTAMPTZ NOT NULL,status VARCHAR(32) NOT NULL);
CREATE TABLE ai_audit(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,action VARCHAR(64) NOT NULL,provider_id UUID,prompt_id UUID,tool_id UUID,session_id UUID,correlation_id UUID,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_ai_prompt_tenant ON ai_prompt(tenant_id,enabled);CREATE INDEX idx_ai_tool_tenant ON ai_tool(tenant_id,enabled);CREATE INDEX idx_ai_session_tenant ON ai_session(tenant_id,created_at);CREATE INDEX idx_ai_audit_tenant ON ai_audit(tenant_id,created_at);
